"""Independent directed fixed-point intervals; integer series only, no Arb/mpmath."""
from fractions import Fraction as F
from math import isqrt
B=220;Q=1<<B
class I:
 __slots__=('l','u')
 def __init__(self,x=0,y=None):
  x=F(x);y=x if y is None else F(y);assert x<=y
  self.l=x.numerator*Q//x.denominator;self.u=-((-y.numerator*Q)//y.denominator)
 @classmethod
 def raw(cls,l,u):
  assert isinstance(l,int) and isinstance(u,int) and l<=u
  o=object.__new__(cls);o.l=l;o.u=u;return o
 def __add__(x,y):
  y=asI(y);return I.raw(x.l+y.l,x.u+y.u)
 __radd__=__add__
 def __neg__(x):return I.raw(-x.u,-x.l)
 def __sub__(x,y):return x+-asI(y)
 def __rsub__(x,y):return asI(y)+-x
 def __mul__(x,y):
  y=asI(y);v=(x.l*y.l,x.l*y.u,x.u*y.l,x.u*y.u);return I.raw(min(v)//Q,-((-max(v))//Q))
 __rmul__=__mul__
 def inv(x):
  assert not x.l<=0<=x.u
  return I.raw(Q*Q//x.u,-((-Q*Q)//x.l))
 def __truediv__(x,y):return x*asI(y).inv()
 def __rtruediv__(x,y):return asI(y)*x.inv()
 def __pow__(x,n):
  assert isinstance(n,int) and n>=0
  o=I(1);t=x
  while n:
   if n&1:o=o*t
   t=t*t;n//=2
  return o
 def lower(x):return F(x.l,Q)
 def upper(x):return F(x.u,Q)
 def positive(x):return x.l>0
 def sqrt(x):
  assert x.l>=0
  return I.raw(isqrt(x.l*Q),isqrt(x.u*Q)+(isqrt(x.u*Q)**2!=x.u*Q))
 def hull(x,y):return I.raw(min(x.l,y.l),max(x.u,y.u))
def asI(x):return x if isinstance(x,I) else I(x)
def _logratio(y):
 # y=(z-1)/(z+1), z in[1,2], so 0<=y<=1/3.
 y=asI(y);assert y.l>=0 and y.u<=Q//3+1
 yy=y*y;power=y;s=I(0);K=90
 for j in range(K):s+=power/(2*j+1);power*=yy
 # universal remainder using y<=1/3+1/Q; the represented y is itself exact
 # interval encloser, true y<=1/3. The outer bound below dominates the true tail.
 rem=F(2,1)*F(1,3)**(2*K+1)/(F(2*K+1)*(1-F(1,9)))
 return 2*s+I(0,rem)
L2=_logratio(I(F(1,3)))
def logq(v):
 v=F(v);assert v>0;k=v.numerator.bit_length()-v.denominator.bit_length();r=v/F(2)**k
 if r<1:r*=2;k-=1
 if r>=2:r/=2;k+=1
 assert 1<=r<2
 return _logratio(I((r-1)/(r+1)))+k*L2
def log(x):
 x=asI(x);assert x.l>0
 l=logq(x.lower());u=logq(x.upper());return I.raw(l.l,u.u)
def _expq(v):
 v=F(v)
 if v<0:return _expq(-v).inv()
 k=0
 while v>F(1,16):v/=2;k+=1
 x=I(v);term=I(1);s=I(1);K=55
 for j in range(1,K+1):term=term*x/j;s+=term
 # bound the exact analytic remainder above the finite Taylor polynomial.
 first=F(1,16)**(K+1)
 from math import factorial
 rem=first/F(factorial(K+1))/(1-F(1,16*(K+2)))
 z=s+I(0,rem)
 for _ in range(k):z=z*z
 return z
def exp(x):
 x=asI(x);l=_expq(x.lower());u=_expq(x.upper());return I.raw(l.l,u.u)
def atanq(q):
 q=F(q);assert 0<q<1;power=q;s=F(0);K=90
 for j in range(K):s+=(-1 if j%2 else 1)*power/(2*j+1);power*=q*q
 rem=power/(2*K+1);return I(s-rem,s+rem)
PI=16*atanq(F(1,5))-4*atanq(F(1,239))
def selftest():
 # Exact signed arithmetic and representation boundary tests.
 for a in [F(-19,7),F(-1,3),F(0),F(1,7),F(5,3)]:
  x=I(a);assert x.lower()<=a<=x.upper()
  for b in [F(-17,9),F(-1,2),F(1,13),F(2)]:
   y=I(b)
   for z,v in [(x+y,a+b),(x*y,a*b),(x-y,a-b),(x/y,a/b)]:assert z.lower()<=v<=z.upper()
 for v in [F(0),F(1,9),F(2),F(16,25)]:
  z=I(v).sqrt();assert z.lower()**2<=v<=z.upper()**2
 assert log(1).l<=0<=log(1).u and exp(0).l<=Q<=exp(0).u
 for a in [F(1,100),F(1),F(5),F(100000)]:
  z=exp(log(a));assert z.lower()<=a<=z.upper()
 assert PI.lower()>F(314,100) and PI.upper()<F(22,7)
 return True

